-- ============================================================
--  Тема «Прислівники» у структурованому форматі
--  Згенеровано з mig/adverbs.js — вручну не редагувати.
--  Потребує 06_theory_structure.sql. Повторний запуск безпечний.
-- ============================================================
begin;

alter table public.theory_blocks drop constraint if exists theory_blocks_kind_check;
alter table public.theory_blocks add constraint theory_blocks_kind_check
  check (kind in ('prose', 'hero', 'cases', 'formula', 'traps', 'pairs'));

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g0$th_hero$g0$, $g1$Прислівники$g1$, $g2$elementary$g2$, $g3$hero$g3$, $g4${"title":"Adverbs","chips":["Англійська граматика","Прислівники"],"lead":"Слово, що описує <b>дію, якість або все речення</b>: як, де, коли, як часто, наскільки. Найважче — не поплутати прислівник із прикметником і знати, де його поставити.","diagramTitle":"Від прикметника до прислівника","diagram":[{"role":"прикметник","label":"quick · careful · happy","tone":"neutral"},{"role":"закінчення","label":"+ly · +ly · y→ily","tone":"colour"},{"role":"прислівник","label":"quickly · carefully · happily","tone":"noun"}],"diagramNote":"Adjective + -ly → Adverb"}$g4$::jsonb, null, 0
from public.topics where slug = $g5$adverbs$g5$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = null, position = excluded.position;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g6$th_8$g6$, $g7$Що описує прислівник і які він буває$g7$, $g8$elementary$g8$, $g9$cases$g9$, $g10${"step":"Типи","kicker":"Базове розуміння","lead":"Прислівник описує <b>дієслово, прикметник, інший прислівник або все речення</b>. Це може бути одне слово (<i>carefully</i>) або словосполучення (<i>in the morning</i>). Типів п'ять — за питанням, на яке він відповідає.","cards":[{"icon":"◐","title":"Manner — як?","text":"Спосіб дії.","example":"He drives <b>carefully</b>.","examplePlain":"He drives carefully."},{"icon":"⌖","title":"Place — де?","text":"Місце дії.","example":"Your bag is <b>here</b>.","examplePlain":"Your bag is here."},{"icon":"◷","title":"Time — коли?","text":"Час дії.","example":"They'll leave <b>tomorrow</b>.","examplePlain":"They'll leave tomorrow."},{"icon":"↻","title":"Frequency — як часто?","text":"Повторюваність.","example":"He <b>sometimes</b> goes fishing.","examplePlain":"He sometimes goes fishing."},{"icon":"▮","title":"Degree — наскільки?","text":"Ступінь якості чи дії.","example":"She is <b>very</b> polite.","examplePlain":"She is very polite."}]}$g10$::jsonb, null, 1
from public.topics where slug = $g11$adverbs$g11$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = null, position = excluded.position;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g12$th_9$g12$, $g13$Утворення прислівників: -ly та його правопис$g13$, $g14$elementary$g14$, $g15$formula$g15$, $g16${"step":"Утворення","kicker":"Архітектура форми","lead":"Більшість прислівників утворюється додаванням <b>-ly</b> до прикметника. Правопис змінюється лише за кількох умов.","tiles":[{"role":"звичайний випадок","label":"+ -ly","tone":"neutral"},{"role":"приголосний + y","label":"-y → -ily","tone":"colour"},{"role":"-le","label":"-e → -y","tone":"origin"},{"role":"-ic","label":"+ -ally","tone":"material"}],"legend":[{"tone":"neutral","label":"serious – seriously, quick – quickly, careful – carefully, awful – awfully"},{"tone":"colour","label":"happy – happily"},{"tone":"origin","label":"gentle – gently"},{"tone":"material","label":"dramatic – dramatically"}],"examples":[{"text":"happy → <b>happily</b>","plain":"happy, happily","note":"y → ily"},{"text":"gentle → <b>gently</b>","plain":"gentle, gently","note":"-le → -ly"},{"text":"careful → <b>carefully</b>","plain":"careful, carefully","note":"-l → -ly: дві l"}],"note":"Прикметник на <b>-e</b> бере <i>-ly</i> без змін: <i>polite → politely</i>. Винятки — у вкладках нижче.","tabs":[{"title":"Винятки на -e","html":"<p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\">Зазвичай <b>-e</b> лишається: <span class=\"font-mono\">polite → politely</span>. Але є слово, де вона зникає:</p><div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">true → <b>truly</b></div>"},{"title":"Винятки на -ic","html":"<p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\">Правило <b>-ic → -ally</b> має одне виключення:</p><div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">dramatic → dramatic<b>ally</b> &nbsp;АЛЕ&nbsp; public → public<b>ly</b></div>"}]}$g16$::jsonb, null, 2
from public.topics where slug = $g17$adverbs$g17$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = null, position = excluded.position;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g18$th_10$g18$, $g19$Стоп-пастка: прислівник чи прикметник$g19$, $g20$elementary$g20$, $g21$traps$g21$, $g22${"step":"Стоп-пастка","kicker":"Типові помилки","lead":"Помилки тут виникають з двох причин: слово на <b>-ly</b> виявляється прикметником, або дві форми одного слова мають різне значення.","items":[{"title":"«Вона привітала мене дружньо»","bad":"She greeted me friendlily.","good":"She greeted me <b>in a friendly way</b>.","goodPlain":"She greeted me in a friendly way.","rule":"<i>friendly</i> — прикметник, а не прислівник. Від таких слів (lonely, lively, silly, lovely, elderly…) прислівник утворюють описово: <i>in a … way/manner</i>."},{"title":"«Тато наполегливо працює»","bad":"Dad works hardly.","good":"Dad works <b>hard</b>.","goodPlain":"Dad works hard.","rule":"<i>hard</i> = наполегливо. А <i>hardly</i> означає «майже не» — і сенс зовсім інший."},{"title":"«Вона прийшла пізно»","bad":"She arrived lately.","good":"She arrived <b>late</b>.","goodPlain":"She arrived late.","rule":"<i>late</i> = пізно, <i>lately</i> = останнім часом."},{"title":"«Птах летів високо»","bad":"The bird flew highly above the trees.","good":"The bird flew <b>high</b> above the trees.","goodPlain":"The bird flew high above the trees.","rule":"<i>high</i> = високо (фізично), <i>highly</i> = дуже (оцінка): <i>highly recommended</i>."},{"title":"«Він доволі високий чоловік»","bad":"He is a quite tall man.","good":"He is <b>quite a</b> tall man.","goodPlain":"He is quite a tall man.","rule":"<i>quite</i> стоїть перед артиклем: <i>quite a</i>."}]}$g22$::jsonb, null, 3
from public.topics where slug = $g23$adverbs$g23$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = null, position = excluded.position;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g24$th_12$g24$, $g25$Одна форма для прикметника й прислівника$g25$, $g26$intermediate$g26$, $g27$formula$g27$, $g28${"step":"Одна форма","kicker":"Роль у реченні","lead":"Низка слів має <b>однакову форму</b> і як прикметник, і як прислівник. Розрізняємо за роллю: описує іменник — прикметник, описує дієслово — прислівник.","tiles":[{"role":"описує іменник","label":"adjective","tone":"opinion"},{"role":"описує дієслово","label":"adverb","tone":"colour"}],"legend":[{"tone":"opinion","label":"The lake is deep. · These biscuits are very hard. · a weekly magazine"},{"tone":"colour","label":"They went deep into the forest. · He tried hard. · It comes out weekly."}],"examples":[{"text":"The lake is <b>deep</b>. / They went <b>deep</b> into the forest.","plain":"The lake is deep. They went deep into the forest.","note":"adj / adv"},{"text":"These biscuits are <b>hard</b>. / He tried <b>hard</b>.","plain":"These biscuits are hard. He tried hard.","note":"adj / adv"},{"text":"'Bella Donna' is a <b>weekly</b> magazine. / It comes out <b>weekly</b>.","plain":"Bella Donna is a weekly magazine. It comes out weekly.","note":"adj / adv"}],"note":"<b>Типова помилка:</b> <s>Dad works hardly.</s> → <i>Dad works hard.</i>","tabs":[{"title":"Список слів","html":"<p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\">Ці слова мають однакову форму:</p><div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">hard · fast · free · high · low · deep · early · late · long · near · straight · right · wrong</div><p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\">А також слова з часом:</p><div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">hourly · daily · weekly · monthly · yearly</div>"},{"title":"Прикметники на -ly","html":"<p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\">Деякі слова на <b>-ly</b> — прикметники. Прислівник від них описовий: <span class=\"font-mono\">in a … way/manner</span>.</p><div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">elderly · cowardly · friendly · likely · deadly · lively · lonely · silly · ugly · lovely</div><p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\"><i>She's a lively child.</i> (прикметник) · <i>She greeted me <b>in a friendly way</b>.</i></p>"},{"title":"Розмовне без -ly","html":"<p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\">У розмовній мові <b>-ly</b> часто опускають:</p><div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">loud(ly) · cheap(ly) · quick(ly) · tight(ly) · fair(ly) · slow(ly)</div><p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\"><i>Come here quick!</i></p>"}]}$g28$::jsonb, null, 4
from public.topics where slug = $g29$adverbs$g29$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
