insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g30$th_13$g30$, $g31$Позиція та порядок прислівників$g31$, $g32$intermediate$g32$, $g33$formula$g33$, $g34${"step":"Позиція","kicker":"Де ставити","lead":"Прислівники зазвичай стоять <b>після дієслова</b>, але <b>перед прикметником</b>, іншим прислівником чи дієприкметником. Коли їх кілька, діє порядок: спосіб → місце → час.","tiles":[{"role":"1","label":"MANNER","tone":"opinion"},{"role":"2","label":"PLACE","tone":"size"},{"role":"3","label":"TIME","tone":"colour"}],"legend":[{"tone":"opinion","label":"manner — як? (quietly)"},{"tone":"size","label":"place — де? (in his cot)"},{"tone":"colour","label":"time — коли? (all night long)"}],"examples":[{"text":"The baby slept <b>quietly</b> in his cot <b>all night long</b>.","plain":"The baby slept quietly in his cot all night long.","note":"manner – place – time"},{"text":"He came <b>to work</b> <b>by bus</b> <b>this morning</b>.","plain":"He came to work by bus this morning.","note":"дієслово руху: place – manner – time"}],"note":"З дієсловами руху (<i>go, come, leave</i>) порядок інший: <b>PLACE → MANNER → TIME</b>.","tabs":[{"title":"Manner","html":"<p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\">Перед основним дієсловом, після допоміжного або в кінці речення:</p><div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">She <b>easily</b> passed the exam.<br>We are <b>eagerly</b> waiting.</div>"},{"title":"Degree","html":"<p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\"><i>absolutely, completely, totally, extremely, very, quite, rather</i> — перед прикметником чи прислівником, але після допоміжного дієслова:</p><div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">This is <b>totally</b> unacceptable.<br>I don't <b>quite</b> understand.</div>"},{"title":"Frequency","html":"<p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\">Після допоміжних дієслів і <i>to be</i>, перед основним дієсловом:</p><div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">He is <b>always</b> ready to help.<br>Sam <b>often</b> complains.</div>"},{"title":"Place, time, soon","html":"<p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\"><b>Place</b> і <b>time</b> зазвичай стоять у кінці. А <i>soon, now, then</i> — перед основним дієсловом:</p><div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">There is a café <b>nearby</b>.<br>I'll meet you <b>tomorrow</b>.<br>She <b>then</b> told him what had happened.</div>"}]}$g34$::jsonb, null, 5
from public.topics where slug = $g35$adverbs$g35$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = null, position = excluded.position;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g36$th_14$g36$, $g37$Fairly – Quite – Rather – Pretty$g37$, $g38$advanced$g38$, $g39$formula$g39$, $g40${"step":"Сила прислівника","kicker":"Тонкощі ступеня","lead":"Чотири прислівники ступеня різняться силою: <b>fairly &lt; quite &lt; rather / pretty &lt; very</b>.","tiles":[{"role":"слабкий","label":"fairly","tone":"size"},{"role":"середній","label":"quite","tone":"origin"},{"role":"сильний","label":"rather / pretty","tone":"colour"}],"legend":[{"tone":"size","label":"a/an + fairly: досить, але не дуже — This is a fairly good CD, but it's not the best."},{"tone":"origin","label":"quite + a/an: достатньо — This is quite a good CD. You ought to buy it."},{"tone":"colour","label":"rather + a/an або a/an + rather; a/an + pretty — I expected the book to be boring, but it was rather interesting."}],"examples":[{"text":"He had <b>a pretty</b> nasty accident.","plain":"He had a pretty nasty accident.","note":"pretty = розмовне rather"},{"text":"Ted is <b>rather more</b> experienced than Alec.","plain":"Ted is rather more experienced than Alec.","note":"rather + comparative"},{"text":"She spends <b>rather too</b> much money.","plain":"She spends rather too much money.","note":"rather + too"}],"note":"<b>Типова помилка:</b> <s>He is a quite tall man.</s> → <i>He is quite a tall man.</i>","tabs":[{"title":"Quite = повністю","html":"<p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\">З абсолютними прикметниками <b>quite</b> означає «повністю»:</p><div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">horrible · ridiculous · brilliant · amazing · useless · impossible · true · exhausted · certain</div><p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\"><i>This machine is quite useless.</i></p>"}]}$g40$::jsonb, null, 6
