update public.theory_blocks tb set kind = 'prose', content_json = null, position = 7
  from public.topics t where t.id = tb.topic_id and t.slug = $g42$adverbs$g42$ and tb.block_key = $g43$th_11$g43$;

commit;

select tb.kind, tb.level, tb.position, tb.block_key, tb.title from public.theory_blocks tb
  join public.topics t on t.id = tb.topic_id where t.slug = $g44$adverbs$g44$ order by tb.position;
